def larg_nnum(list1, n):
    # Handle edge cases where n is larger than the list length or non-positive
    if n <= 0 or n > len(list1):
        return []

    # Use a min-heap to keep track of the n largest numbers
    import heapq
    heap = []

    for item in list1:
        if len(heap) < n:
            heapq.heappush(heap, item)
        else:
            if item > heap[0]:
                heapq.heappop(heap)
                heapq.heappush(heap, item)

    # Return the heap sorted in descending order
    return sorted(heap, reverse=True)
```

